import random
def brute_force(target, nums):
    best = 0
    for start in range(len(nums)):
        total = 0
        for end in range(start, len(nums)):
            total += nums[end]
            if total >= target:
                if best == 0 or end - start + 1 < best:
                    best = end - start + 1
                break
    return best
def agrees_with_brute_force_on_small_random_lists():
    rng = random.Random(21)
    for _ in range(300):
        nums = [rng.randint(1, 6) for _ in range(rng.randint(0, 9))]
        target = rng.randint(1, 20)
        got = min_subarray_len(target, list(nums))
        assert got == brute_force(target, nums), f"min_subarray_len({target}, {nums}) returned {got}, expected {brute_force(target, nums)}"
    return True
